#include <stdlib.h>
#include <math.h>
#include <string.h>
/* M dense n x n, threshold r. Build CSR of edges with M<r. Solve assignment via sparse SAP.
   returns 0 ok, 1 infeasible(sparse), 2 dual violated. col4row out. */
typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}h[i]=last;return top;}

int solve(int n,const double*M,double r,int*col4row,double*extra_r){
  int *rp=malloc((n+1)*sizeof(int));
  int cap=n*32; int *ci=malloc(cap*sizeof(int)); double *cv=malloc(cap*sizeof(double));
  int ne=0; rp[0]=0;
  for(int i=0;i<n;i++){const double*row=M+(size_t)i*n;
    for(int j=0;j<n;j++){double c=row[j]; if(c<r){ if(ne>=cap){cap*=2;ci=realloc(ci,cap*sizeof(int));cv=realloc(cv,cap*sizeof(double));} ci[ne]=j;cv[ne]=c;ne++;}}
    rp[i+1]=ne;}
  double *u=calloc(n,sizeof(double)),*v=calloc(n,sizeof(double)),*dist=malloc(n*sizeof(double));
  int *row4col=malloc(n*sizeof(int)),*pred=malloc(n*sizeof(int)),*done=calloc(n,sizeof(int)),*seen=calloc(n,sizeof(int));
  int *SC=malloc(n*sizeof(int)),*SR=malloc(n*sizeof(int)),*touched=malloc(n*sizeof(int));
  HE*h=malloc((ne+n+1)*sizeof(HE));
  for(int i=0;i<n;i++){col4row[i]=-1;row4col[i]=-1;}
  /* greedy init: column reduction v[j]=min_i c over edges; then row assign if tight & free */
  for(int j=0;j<n;j++)v[j]=INFINITY;
  for(int i=0;i<n;i++)for(int e=rp[i];e<rp[i+1];e++){if(cv[e]<v[ci[e]])v[ci[e]]=cv[e];}
  for(int j=0;j<n;j++)if(v[j]==INFINITY)v[j]=0;
  for(int i=0;i<n;i++){double best=INFINITY;int bj=-1;for(int e=rp[i];e<rp[i+1];e++){double rc=cv[e]-v[ci[e]];if(rc<best){best=rc;bj=ci[e];}}
    if(bj<0){free(rp);free(ci);free(cv);free(u);free(v);free(dist);free(row4col);free(pred);free(done);free(seen);free(SC);free(SR);free(touched);free(h);return 1;}
    u[i]=best; if(row4col[bj]<0 && best<=0){row4col[bj]=i;col4row[i]=bj;}}
  /* note: u[i]=min rc may be negative? rc>=0 since v[j]=min col. ok */
  int status=0;
  for(int cur=0;cur<n;cur++){ if(col4row[cur]>=0)continue;
    int hs=0,nsc=0,nsr=0,nt=0; int i=cur; double minVal=0; int sink=-1;
    SR[nsr++]=i;
    while(1){
      for(int e=rp[i];e<rp[i+1];e++){int j=ci[e]; if(done[j])continue; double d=minVal+cv[e]-u[i]-v[j];
        if(!seen[j]||d<dist[j]){if(!seen[j]){seen[j]=1;touched[nt++]=j;} dist[j]=d;pred[j]=i;hpush(h,&hs,d,j);}}
      int j=-1;
      while(hs>0){HE t=hpop(h,&hs); if(done[t.j]||t.d>dist[t.j])continue; j=t.j;minVal=t.d;break;}
      if(j<0){status=1;break;}
      done[j]=1;SC[nsc++]=j;
      if(row4col[j]<0){sink=j;break;}
      i=row4col[j];SR[nsr++]=i;
    }
    if(status)break;
    u[cur]+=minVal;
    for(int k=1;k<nsr;k++){int ii=SR[k];u[ii]+=minVal-dist[col4row[ii]];}
    for(int k=0;k<nsc;k++){int jj=SC[k];v[jj]-=minVal-dist[jj];}
    int j=sink;
    while(1){int ii=pred[j];row4col[j]=ii;int tmp=col4row[ii];col4row[ii]=j;if(ii==cur)break;j=tmp;}
    for(int k=0;k<nt;k++){seen[touched[k]]=0;done[touched[k]]=0;}
  }
  if(!status){ /* dual check on full matrix */
    for(int i=0;i<n&&!status;i++){const double*row=M+(size_t)i*n;double ui=u[i];
      for(int j=0;j<n;j++){if(row[j]-ui-v[j]<-1e-12){status=2;break;}}}
  }
  free(rp);free(ci);free(cv);free(u);free(v);free(dist);free(row4col);free(pred);free(done);free(seen);free(SC);free(SR);free(touched);free(h);
  return status;
}
