import os, ctypes
import numpy as np

_dir = os.path.dirname(os.path.abspath(__file__))
_lib = None
try:
    _lib = ctypes.CDLL(os.path.join(_dir, "sap.so"))
    _lib.solve.restype = ctypes.c_int
    _lib.solve.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_double, ctypes.c_void_p]
except Exception:
    _lib = None


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if (_lib is not None and n == b.shape[0] and n > 0 and M.shape == (n, n)
                and np.all(a == a[0]) and np.all(b == a[0])):
            col = np.empty(n, dtype=np.int32)
            mx = float(M.max())
            r = max(2.5 / np.sqrt(n), 1e-300) * (mx / 1.0 if mx > 0 else 1.0)
            r = min(r, mx) if mx > 0 else 1.0
            for _ in range(60):
                st = _lib.solve(n, M.ctypes.data, ctypes.c_double(r), col.ctypes.data)
                if st == 0:
                    G = np.zeros((n, n))
                    G[np.arange(n), col] = a[0]
                    return {"transport_plan": G}
                if r > mx:
                    break
                r *= 2.0
        import ot
        return {"transport_plan": ot.lp.emd(a, b, M, check_marginals=False)}
