#include <stdlib.h>
#include <math.h>
#include <string.h>
typedef struct {double d; int j;} HE;
static inline void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static inline HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}h[i]=last;return top;}

int solve(int n,const double*M,double r,int*col4row,int*rounds_out){
  size_t nn=(size_t)n*n;
  unsigned char*mask=malloc(nn);
  for(size_t k=0;k<nn;k++)mask[k]=M[k]<r;
  /* ensure each row & column has at least its min */
  for(int i=0;i<n;i++){const double*row=M+(size_t)i*n;int b=0;for(int j=1;j<n;j++)if(row[j]<row[b])b=j;mask[(size_t)i*n+b]=1;}
  double *u=calloc(n,sizeof(double)),*v=malloc(n*sizeof(double)),*dist=malloc(n*sizeof(double));
  for(int j=0;j<n;j++)v[j]=INFINITY;
  for(int i=0;i<n;i++){const double*row=M+(size_t)i*n;for(int j=0;j<n;j++)if(row[j]<v[j])v[j]=row[j];}
  for(int j=0;j<n;j++){int b=0;for(int i=1;i<n;i++)if(M[(size_t)i*n+j]<M[(size_t)b*n+j])b=i;mask[(size_t)b*n+j]=1;}
  int *row4col=malloc(n*sizeof(int)),*pred=malloc(n*sizeof(int));
  unsigned char*done=calloc(n,1),*seen=calloc(n,1);
  int *SC=malloc(n*sizeof(int)),*SR=malloc(n*sizeof(int)),*touched=malloc(n*sizeof(int));
  int *rp=malloc((n+1)*sizeof(int)); int cap=0; int*ci=NULL; double*cv=NULL; HE*h=NULL;
  for(int i=0;i<n;i++){col4row[i]=-1;row4col[i]=-1;}
  /* u=0, v=colmin: feasible. greedy tight assignment */
  for(int i=0;i<n;i++){const double*row=M+(size_t)i*n;double best=INFINITY;int bj=-1;
    for(int j=0;j<n;j++){double rc=row[j]-v[j];if(rc<best||(rc==best&&row4col[j]<0&&bj>=0&&row4col[bj]>=0)){best=rc;bj=j;}}
    u[i]=best; if(row4col[bj]<0){row4col[bj]=i;col4row[i]=bj;}}
  int status=0,rounds=0;
  while(1){
    rounds++;
    int ne=0; rp[0]=0;
    for(int i=0;i<n;i++){const unsigned char*mr=mask+(size_t)i*n;for(int j=0;j<n;j++)ne+=mr[j];}
    if(ne>cap){cap=ne;ci=realloc(ci,cap*sizeof(int));cv=realloc(cv,cap*sizeof(double));h=realloc(h,(cap+n+1)*sizeof(HE));}
    ne=0;
    for(int i=0;i<n;i++){const unsigned char*mr=mask+(size_t)i*n;const double*row=M+(size_t)i*n;
      for(int j=0;j<n;j++)if(mr[j]){ci[ne]=j;cv[ne]=row[j];ne++;} rp[i+1]=ne;}
    for(int cur=0;cur<n;cur++){ if(col4row[cur]>=0)continue;
      int hs=0,nsc=0,nsr=0,nt=0; int i=cur; double minVal=0; int sink=-1;
      SR[nsr++]=i;
      while(1){
        double ui=u[i];
        for(int e=rp[i];e<rp[i+1];e++){int j=ci[e]; if(done[j])continue; double d=minVal+cv[e]-ui-v[j];
          if(!seen[j]||d<dist[j]){if(!seen[j]){seen[j]=1;touched[nt++]=j;} dist[j]=d;pred[j]=i;hpush(h,&hs,d,j);}}
        int j=-1;
        while(hs>0){HE t=hpop(h,&hs); if(done[t.j]||t.d>dist[t.j])continue; j=t.j;minVal=t.d;break;}
        if(j<0){status=1;break;}
        done[j]=1;SC[nsc++]=j;
        if(row4col[j]<0){sink=j;break;}
        i=row4col[j];SR[nsr++]=i;
      }
      for(int k=0;k<nt;k++){seen[touched[k]]=0;done[touched[k]]=0;}
      if(status)break;
      u[cur]+=minVal;
      for(int k=1;k<nsr;k++){int ii=SR[k];u[ii]+=minVal-dist[col4row[ii]];}
      for(int k=0;k<nsc;k++){int jj=SC[k];v[jj]-=minVal-dist[jj];}
      int j=sink;
      while(1){int ii=pred[j];row4col[j]=ii;int tmp=col4row[ii];col4row[ii]=j;if(ii==cur)break;j=tmp;}
    }
    if(status)break;
    /* full check */
    int viol=0;
    for(int i=0;i<n;i++){const double*row=M+(size_t)i*n;double ui=u[i];unsigned char*mr=mask+(size_t)i*n;
      for(int j=0;j<n;j++){double rc=row[j]-ui-v[j];if(rc<-1e-12){mr[j]=1;viol++;if(rc+v[j]<v[j]){} }}}
    if(!viol)break;
    if(rounds>50){status=3;break;}
    for(int i=0;i<n;i++){const double*row=M+(size_t)i*n;double ui=u[i];for(int j=0;j<n;j++){double t=row[j]-ui;if(t<v[j])v[j]=t;}}
    for(int i=0;i<n;i++){int j=col4row[i];if(M[(size_t)i*n+j]-u[i]-v[j]>1e-12){col4row[i]=-1;row4col[j]=-1;}}
  }
  *rounds_out=rounds;
  free(mask);free(rp);free(ci);free(cv);free(u);free(v);free(dist);free(row4col);free(pred);free(done);free(seen);free(SC);free(SR);free(touched);free(h);
  return status;
}
