{"command": "cat > sap.c <<'EOF'
#include <stdlib.h>
#include <math.h>
#include <string.h>
typedef struct {double d; int j;} HE;
static inline void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static inline HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;while(1){int c=2*i+1;if(c>=n)break;if(c+1<n&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}h[i]=last;return top;}

/* edges stored per row as dynamic arrays */
typedef struct {int *j; double *c; int n, cap;} Row;
static inline void addE(Row*R,int j,double c){if(R->n>=R->cap){R->cap=R->cap?R->cap*2:16;R->j=realloc(R->j,R->cap*sizeof(int));R->c=realloc(R->c,R->cap*sizeof(double));}R->j[R->n]=j;R->c[R->n]=c;R->n++;}

int solve(int n,const double*M,double r,int*x,int*info){
  Row*R=calloc(n,sizeof(Row));
  double *v=malloc(n*sizeof(double)),*dist=malloc(n*sizeof(double));
  int *y=malloc(n*sizeof(int)),*pred=malloc(n*sizeof(int)),*cmin=malloc(n*sizeof(int));
  unsigned char*done=calloc(n,1),*seen=calloc(n,1);
  int *SC=malloc(n*sizeof(int)),*touched=malloc(n*sizeof(int)),*fr=malloc(n*sizeof(int));
  int hcap=n*64; HE*h=malloc(hcap*sizeof(HE));
  for(int j=0;j<n;j++){v[j]=INFINITY;cmin[j]=0;}
  for(int i=0;i<n;i++){const double*row=M+(size_t)i*n;Row*Ri=&R[i];
    for(int j=0;j<n;j++){double c=row[j]; if(c<v[j]){v[j]=c;cmin[j]=i;} if(c<r)addE(Ri,j,c);}}
  for(int i=0;i<n;i++){x[i]=-1;y[i]=-1;}
  /* column reduction */
  for(int j=n-1;j>=0;j--){int i=cmin[j]; double c=M[(size_t)i*n+j]; if(!(c<r))addE(&R[i],j,c); if(x[i]<0){x[i]=j;y[j]=i;}}
  int nf=0; for(int i=0;i<n;i++) if(x[i]<0) fr[nf++]=i;
  /* ensure each row nonempty */
  for(int k=0;k<nf;k++){int i=fr[k]; if(R[i].n==0){const double*row=M+(size_t)i*n;int b=0;for(int j=1;j<n;j++)if(row[j]<row[b])b=j;addE(&R[i],b,row[b]);}}
  /* augmenting row reduction, 2 passes */
  for(int pass=0;pass<2;pass++){
    int k=0,prevnf=nf; nf=0;
    while(k<prevnf){int i=fr[k++];
      Row*Ri=&R[i]; double u1=INFINITY,u2=INFINITY;int j1=-1,j2=-1;
      for(int e=0;e<Ri->n;e++){double h_=Ri->c[e]-v[Ri->j[e]];int j=Ri->j[e];
        if(h_<u2){ if(h_>=u1){u2=h_;j2=j;} else {u2=u1;j2=j1;u1=h_;j1=j;} }}
      if(j1<0) {fr[nf++]=i; continue;}
      int i0=y[j1];
      if(j2>=0 && u1<u2){ v[j1]-= (u2-u1); }
      else if(i0>=0 && j2>=0){ j1=j2; i0=y[j2]; }
      if(i0>=0){ if(u1<u2) fr[--k]=i0; else fr[nf++]=i0; x[i0]=-1; }
      x[i]=j1; y[j1]=i;
    }
  }
  int status=0,rounds=0; long scans=0;
  while(1){
    rounds++;
    nf=0; for(int i=0;i<n;i++) if(x[i]<0) fr[nf++]=i;
    int incomplete=0;
    for(int f=0;f<nf;f++){int cur=fr[f];
      int hs=0,nsc=0,nt=0; int i=cur; double minVal=0; int sink=-1; double ui=0;
      while(1){
        Row*Ri=&R[i];
        if(hs+Ri->n>=hcap){hcap=(hs+Ri->n)*2;h=realloc(h,hcap*sizeof(HE));}
        for(int e=0;e<Ri->n;e++){int j=Ri->j[e]; if(done[j])continue; double d=minVal+Ri->c[e]-v[j]-ui;
          if(!seen[j]){seen[j]=1;touched[nt++]=j;dist[j]=d;pred[j]=i;hpush(h,&hs,d,j);}
          else if(d<dist[j]){dist[j]=d;pred[j]=i;hpush(h,&hs,d,j);}}
        int j=-1;
        while(hs>0){HE t=hpop(h,&hs); if(done[t.j]||t.d>dist[t.j])continue; j=t.j;minVal=t.d;break;}
        if(j<0)break;
        done[j]=1;SC[nsc++]=j;scans++;
        if(y[j]<0){sink=j;break;}
        i=y[j]; ui=0;
