      for(int k=0;k<nsc;k++){int jj=SC[k];v[jj]-=minVal-dist[jj];}
      int j=sink;
      while(1){int ii=pred[j];y[j]=ii;int t2=x[ii];x[ii]=j;if(ii==cur)break;j=t2;}
    }
